<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('quotations.approve');verify_csrf();$pdo=staff_db();feature_table($pdo,'approval_requests');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=fint('id');$decision=fpost('decision');if(in_array($decision,['approved','rejected'],true)){$pdo->prepare('UPDATE approval_requests SET status=?,assigned_approver=?,decided_at=NOW() WHERE id=?')->execute([$decision,$staff['id'],$id]);$pdo->prepare('INSERT INTO approval_actions(approval_request_id,staff_id,action,comment) VALUES(?,?,?,?)')->execute([$id,$staff['id'],$decision,fpost('notes')?:null]);flash('success','Approval decision saved.');}staff_redirect('staff/admin/approvals.php');}
$rows=db_rows($pdo,'SELECT a.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) requester FROM approval_requests a LEFT JOIN staff s ON s.id=a.requested_by ORDER BY FIELD(a.status,"pending","approved","rejected","cancelled"),a.created_at DESC');$pageTitle='Approvals';require __DIR__.'/../../includes/staff/header.php';module_head('Management','Approval Workflow','Review quotation discounts, purchases and other controlled actions.');?>
<section class="staff-panel table-panel"><table><thead><tr><th>Request</th><th>Type</th><th>Requested by</th><th>Reason</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b>Approval #<?=h($r['id'])?></b><small><?=h($r['entity_type'].' #'.$r['entity_id'])?></small></td><td><?=h($r['request_type'])?></td><td><?=h($r['requester']?:'—')?></td><td><?=h($r['reason']?:'—')?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><?php if($r['status']==='pending'):?><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input name="notes" placeholder="Decision note"><button class="btn primary" name="decision" value="approved">Approve</button><button class="btn" name="decision" value="rejected">Reject</button></form><?php else:?>Resolved<?php endif?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>